import { HistoricalDocument } from '../../types';

export const ordenacoesLivro1TitulosXciAC: HistoricalDocument = {
  id: 'ordenacoes-livro-1-titulos-xci-a-c',
  title: 'Ordenações Filipinas — Títulos XCI a C',
  subtitle: 'Dos Contadores dos feitos e custas, assi da Corte, como do Reino',
  date: '1603',
  era: 'Idade Moderna',
  language: 'Português',
  description: `Títulos XCI a C do Livro Primeiro das Ordenações Filipinas: de "Dos Contadores dos feitos e custas, assi da Corte, como do Reino" a "Como os Julgadores e outros Officiaes serão suspensos, quando forem accusados por erros".`,
  parentCollectionId: 'ordenacoes-livro-1',
  sections: [
    {
      id: 'titulo-xci',
      title: `XCI. Dos Contadores dos feitos e custas, assi da Corte, como do Reino`,
      type: 'articles',
      articles: [
        { id: 'of1-txci-preambulo', number: 'Preâmbulo', text: `Os Contadores das custas as contarão, assi as pessoaes, que são para mantimento das pessoas, como as do processo, que são o que os Scrivães e Tabelliães hão de haver da scriptura, e o salario dos Procuradores, e outros quaesquer Officiaes. As quaes não contará outra alguma pessoa na nossa Corte, nem na Relação do Porto, nem nas cidades, villas e lugares, onde Contadores de custas houver. E sendo a conta per outrem feita, seja nenhuma e de nenhum effeito, e torne-se a fazer per o Contador, a que pertencer. E aquelle, que a der a fazer a outrem, pague ao Contador de pena o dobro do que houvera de haver da tal conta, além do seu salario ordenado, que lhe della montar. E sendo o Contador suspeito, ou impedido por alguma cousa, porque a não possa fazer; ou se depois de feita, as partes allegarem erro de conta, em taes casos, se for na Casa da Supplicação, ou na do Porto, os Juizes da Chancellaria, e nas cidades, villas e lugares, o Juiz do feito commetterão as taes contas ao Revedor, se o houver para isso ordenado per Nós: e não o havendo, a huma pessoa, que sem suspeita as possa fazer. E stando a Corte apartada da Casa da Supplicação, o Corregedor da Corte fará a tal commissão.` },
        { id: 'of1-txci-1', number: '1', text: `E bem assi farão as outras contas, que os Julgadores entre partes mandarem fazer nos feitos, que se perante elles tratarem. E neste caso poderão os ditos Julgadores, a requerimentos das partes, ou de cada huma dellas, mandar fazer as contas per outras pessoas, em que se louvarem, havendo causa legitima para isso: ou sendo a qualidade das contas tal, que lhes pareça bem fazer-se assi. E os que assi fizeram as ditas contas entre partes, não levarão mais salarios dellas, que o que lhes for taxado pelo Juiz do feito, que as mandou fazer. E levando mais, ou levando-o sem lhe ser taxado, haverão as penas, que per Nós são postas aos Officiaes, que levam mais do conteúdo em seus Regimentos. E do que for taxado pelo Juiz, não haverá appellação, nem aggravo, se a quantia do principal, sobre que o feito tratava, couber na sua alçada. E não cabendo em sua alçada o principal, sobre que se o feito trata, poderão os Contadores, ou as partes aggravar da taxação da conta per petição na Casa da Supplicação, ou do Porto, para a Mesa grande, e dante outros Julgadores per instrumento de aggravo para os Desembargadores dos Aggravos, a que o conhecimento pertencer. E depois de taxado o salario da conta, o feito tornará a mão do Contador, da qual não sairá, até ser pago do que assi for taxado.` },
        { id: 'of1-txci-2', number: '2', text: `E porque as custas pessoaes se hão de contar aos litigantes, a que forem julgadas, mais e menos, segundo a differença das pessoas, qualidade e stado, no contar dellas se tenha a maneira seguinte. Se a parte, a que as custas forem julgadas, for Cavalleiro, ou Cidadão, ou agraduado em gráo de Bacharel, ou Scudeiro, ou de outra mór condição; ou for Mercador, e fizer certo, que em algumas das nossas Alfandegas dizimou de alguma mercadoria sua, pouco, ou muito, aquelle anno, em que o feito se tratou; ou for Mestre de Não de Castello davante, ou de Navio, que seja de carrego de oitenta toneis, e dahi para cima, contar-lhe-hão quarenta réis por dia para sua pessoa, e quinze para hum criado, e outros quinze para o cavallo, se o trouver.` },
        { id: 'of1-txci-3', number: '3', text: `E quando algumas partes fôrem de tal qualidade, a que se devam contar mais servidores, assi de pé, como Scudeiros, como adiante será declarado, contar-lhe-hão para cada hum servidor de pé a doze réis por dia, e aos Scudeiros, que lhe houverem de ser contados, a quinze réis por dia a cada hum, e quinze para o cavallo.` },
        { id: 'of1-txci-4', number: '4', text: `E aos Moedeiros e Espingardeiros e Besteiros do conto e do monte, assi aposentados, como por aposentar, contarão quarenta réis por dia. E sendo preso cada hum dos sobreditos, contem-lhe cincoenta réis por dia, quer tenha servidor, quer não.` },
        { id: 'of1-txci-5', number: '5', text: `E todos nossos moradores, que per Ordenança hão de ter cevada, quando tiverem cavallo, haverão as custas como os Scudeiros. E os outros nossos criados, que per nossa Ordenança não hão de haver cevada, ainda que cavallo tenham, haverão trinta réis por dia.` },
        { id: 'of1-txci-6', number: '6', text: `E se algum homem, que Scudeiro não seja, allegar, que he abastado, e que costuma ter cavallo, e que sempre trouxe o cavallo no lugar, onde seguio a demanda, em quanto nella andou, contar-lhe-hão custas de sua pessoa, como acima dissemos, que se contem ao Scudeiro.` },
        { id: 'of1-txci-7', number: '7', text: `E quando as molheres de quaesquer pessoas das acima nomeadas seguirem seus feitos per si, assi em vida do marido, como depois, emquanto honrada e honestamente viverem, contar-lh'as-hão, como se deveram contar a seus maridos.` },
        { id: 'of1-txci-8', number: '8', text: `E aos Clerigos de Ordens Sacras, e aos Beneficiados contarão as custas, como aos Cavalleiros.` },
        { id: 'of1-txci-9', number: '9', text: `E ao peão contarão a trinta réis por dia, andando solto, e a cincoenta se for preso, quer tenha servidor, quer não.

Porém, se o tal preso for Official mechanico, e na cadea não usar de seu Officio, como fizera, se fora solto, contar-lhe-hão a sessenta réis por dia. E ás molheres dos ditos peães contarão a trinta réis por dia, sendo soltas, e quarenta, sendo presas, quer tenham quem as sirva, quer não.` },
        { id: 'of1-txci-10', number: '10', text: `E quando algum litigante não seguir seu feito per si em pessoa, e o mandar requerer per outrem, haverá de custas segundo for a qualidade do requerente, não passando do que houvera de haver o que o assi enviou, se per sua pessoa a dita demanda requerêra.` },
        { id: 'of1-txci-11', number: '11', text: `E quando a parte vencedor for morador no lugar, onde se tratar o feito, ou em seu termo, contar-lhe-hão sómente os dias, que pelos termos do feito se mostrar, que appareceu nas audiencias, ou deu inquirição, ou foi ver como juravam as testemunhas, que contra elle se deram.` },
        { id: 'of1-txci-12', number: '12', text: `E porquanto, além dos ditos dias, as partes vão outros muitos dias seguir seus feitos stando conclusos em poder do Julgador, aguardando as audiencias, quando seus feitos hão de sair, e taes dias são incertos, o Contador dará juramento à parte, que diga quantos são esses dias, que pelos termos do feito se não mostram; e os que jurar, se vir que podem caber no tempo, que o processo durou, contar-lhos-ha, não passando de quarenta dias em cada hum anno, postoque a parte jure que são mais, porque isto se costumou sempre assi, e por isso se chamam dias do costume. Os quaes dias se entenderão sómente naquelles, que forem moradores no lugar, onde se tratar a demanda.` },
        { id: 'of1-txci-13', number: '13', text: `E se a parte vencedor não for do lugar e termo, onde se tratar o feito, e vier a esse feito de outro Julgado; contar-lhe-hão os dias, que hi se deteve por elle, e os da ida e vinda, até que chegue a sua casa, a seis legoas por dia, e mais não, e mais tres para se fazer e tirar a sentença. E isto se entenderá, se elle não veio ahi para outra cousa. Que se para negociar outra cousa veio, mais que por seguir o feito (o que ficará em seu juramento), então não haverá custas, senão dos dias, que apparecer em Juizo, ou der inquirição, ou vir jurar as testemunhas, e os dias do costume, como se fosse morador no lugar, e de outra maneira não: e o conhecimento disto pertence ao Contador. E se jurar que veio mais por seguir o feito, que por outra cousa, contar-lhe-ha as custas, postoque ahi negociasse outras cousas, como se sómente negociára a demanda.` },
        { id: 'of1-txci-14', number: '14', text: `E quanto aos feitos dos moradores das Ilhas e lugares de Africa, que vierem a este Regno seguir algum feito, contar-lhes-hão para a tornada os dias, que parecer ao Contador que se podem deter no caminho. E se o feito se acabou em tempo, que não havia Navio para partir deste Regno para as Ilhas, por se não costumar navegar em tal tempo, contar-lhe-hão tambem todos os dias, que por essa causa se detiver. E se ácerca disso o Contador tiver alguma dúvida, de conta della ao Juiz da Chancellaria em cada huma das Relações, e nos outros lugares ao Juiz do feito.` },
        { id: 'of1-txci-15', number: '15', text: `E porque algumas vezes as partes, que vem de outros Julgados, são Alfaiates, ou Capateiros, ou Officiaes de outros mesteres, de que usam continuadamente nos lugares, onde se tratam as demandas, e sómente vão ás audiencias, que se fazem, e acabadas ellas se tornam logo a seus Officios, e se não usassem dos ditos mesteres, poriam mais diligencia em requerer seus feitos, e haveriam mais azinha nelles despacho: a estes que assi usam continuadamente os ditos mesteres, e delles hão proveito, contar-lhes-hão somente os dias, que appareceram em Juizo, ou deram inquirição, ou viram jurar testemunhas, e os dias do costume, como dito he; e isto mesmo se guardará naquelles, que durando a demanda, andam a jornacs continuadamente no lugar da demanda, ou vivem por soldada.` },
        { id: 'of1-txci-16', number: '16', text: `E se for pessoa honrada, que trouxer comsigo algum homem de cavallo, ou de pé, que com elle viva, haverá custas para si, e para seu homem, convem a saber, o de cavallo quinze réis por dia, e quinze para o cavallo, e o de pé a doze réis por dia. E estas mesmas custas levarão as molheres de cada hum dos sobreditos, que comsigo trouxerem os semelhantes servidores, homens, ou molheres. E isto se entenda, que os que assi trouxerem, sejam de idade de quatorze annos acima, e não lhes contem senão hum servidor, postoque mais tragam: salvo se for das pessoas, a que mais servidores mandamos contar.` },
        { id: 'of1-txci-17', number: '47', text: `Item, quando alguma parte traz dous, ou tres feitos, ou mais, ora os traga todos com huma parte, ora com diversas, e for hum feito sentenciado com vencimento de custas, e ao tempo que se contam, stiverem os outros feitos ainda por sentenciar, contar-se-hão ao vencedor todas as custas no feito findo, como se outro não trouxesse. Porém depois, quando os outros feitos forem sentenciados, e nelles, ou em algum delles, houverem de ser contadas custas ao mesmo vencedor, a que já foram contadas, o Contador não lhe contará todos os dias, que já lhe foram contados no outro feito: para o que dará sempre juramento ao vencedor, quando lhe houver de contar custas, para que declare se lhe foram já contadas outras daquelle tempo, que mais durou o feito, em que lhas então conta. Porém aquelle, sobre que assi não são contadas as custas dos dias, que durou o outro feito, em que o vencedor primeiro venceu, será obrigado pagar as custas dos dias, que os ditos feitos duraram, emquanto durou o feito, que primeiro foi sentenciado, soldo à livra per repartição dos dias, em que os feitos juntamente se trataram, as quaes se pagarão àquelle, que já foi primeiro condenado que as pagasse. E não stando elle no lugar, onde se fizer a conta, o Contador as fará entregar ao Mamposteiro dos Captivos desse lugar. E se este, que primeiro foi condenado, e a quem se hão de tornar, as vier pedir até dous mezes do dia, que forem entregues ao Mamposteiro, elle lhas entregará. E não as vindo pedir no dito tempo, ficarão devolutas aos Captivos. E sendo caso que ao tempo, que o Contador conta as ditas custas, os outros feitos forem sentenciados com vencimento de custas de pessoa, o Contador repartirá as ditas custas, de dias de pessoa por outro feito, ou feitos, em que lhe foram julgadas custas, que forem sentenciados ao tempo, os feitos, em que não for custas; porque os feitos, em que não for vencedor em custas, não hão de entrar em repartição, para por elles lhe serem descontados dias alguns.` },
        { id: 'of1-txci-18', number: '18', text: `E porque muitas vezes molheres, que não são de Cavalleiros, nem das pessoas que devem haver custas de Cavalleiros, e assi homens velhos, ou doentes, que não podem vir a pé, vem em bestas alugadas, quando forem vencedores em custas, contar-lhes-hão os alugeres das bestas, em que vieram, fazendo-o certo per testemunhas, ou por scriptura. E não tendo testemunhas, nem scriptura, ficará em seu juramento, comtanto que o que assi jurar, não passe de duzentos réis.` },
        { id: 'of1-txci-19', number: '19', text: `E quando forem julgadas a parte vencedor as custas do processo sómente, conte-lhe todas as custas, que a parte fizer no processo, e mais não. E quando achar que são julgadas em dobro, ou tresdobro, contará todas as custas, que se mostrar que a parte fez em dobro e tresdobro: salvo a assinatura, e o salario do Procurador e conta do Contador, e feito da sentença e Chancellaria della. E não contarão aos Scrivães os traslados das suspeições, que vierem nas appellações, nem das Cartas, per que se tiraram inquirições, como fica dito no Titulo 79: Dos Tabelliaes do Judicial.` },
        { id: 'of1-txci-20', number: '20', text: `E contarão as partes vencedores em custas todas as barcas, que passarem através, em vindo ao feito, e tornando para suas casas, quantas vezes as passarem. E não lhes contem barca de longo do rio, postoque o alleguem, sómente os dias de pessoa a seis legoas por dia, porque assi se costumou sempre.` },
        { id: 'of1-txci-21', number: '21', text: `E aos que vierem per mar de tal lugar, de que podéram vir per terra, se quizeram, contar-lhes-hão a seis legoas por dia. E se vierem de lugar, de que não podiam vir senão per mar, contar-lhes-hão todo o tempo, que andaram no mar, quanto à vinda.` },
        { id: 'of1-txci-22', number: '22', text: `Muitas vezes algumas partes vêm à Corte, e seguem seus feitos, e se chegam a alguns Fidalgos, ou Officiaes de nossa Casa, ou semelhantes pessoas, por divido, criação, ou amizade, que com elles têm, e os acompanham e servem, e lhes dão de comer e gasalhado de pousada e cama. Porém, porque pela maior parte sempre pagam tal gasalhado e comer em outras taes obras, ou semelhantes, e assi as partes recebem perda de sua fazenda em virem, ou mandarem requerer os ditos feitos: mandamos que as custas lhes sejam contadas, como se comeram à sua custa.` },
        { id: 'of1-txci-23', number: '23', text: `E se o feito se tratar na Corte, e a parte vencedor for Procurador, ou Scrivão, ou tal Official, que per bem de seu Officio deve star cada dia nas audiencias, ou se tratar perante o Juiz, e a parte for Tabellião, Procurador, ou Porteiro, a estes não se contem dias de pessoa, nem do costume: porque ainda que tal feito não trouxessem, haviam de ir à audiencia por razão de seus Officios.` },
        { id: 'of1-txci-24', number: '24', text: `Aos Mestres das Ordens, Arcebispos, Bispos, Condes, Prior do Crato da Ordem de S. João do Hospital, contarão até vinte cavalgaduras a cada hum: ao Commendatário de Alcobaça até nove: aos Abbades Bentos até quatro: aos Commendadores Móres e outros Fidalgos até seis: aos Desembargadores, Doutores, Licenciados, Mestres em Theologia, feitos per exame em studo geral, ou Cavalleiros, ou Scudeiros honrados, até quatro cavalgaduras: e a outros Cavalleiros ou Scudeiros de menos condição, huma cavalgadura e dous homens de pé, se os trouxer. E a todas estas pessoas não contarão mais cavalgaduras, postoque mais tragam. E trazendo menos, contar-lhes-hão sómente as que trouxerem. As quaes se lhes contarão, sendo suas proprias e não alheias, e que costumam trazer comsigo, quando vão fóra de suas casas a outra parte. E as que não costumarem trazer comsigo, não lhes serão contadas, quando as trouxerem para seguimento do feito.` },
        { id: 'of1-txci-25', number: '25', text: `E bem assi não será contada cavalgadura a nenhuma pessoa das sobreditas, quando trouxer a demanda no lugar, onde he morador, postoque nas audiencias appareça, e que as ditas cavalgaduras, ou mais, ou menos comsigo traga; sómente lhe serão contadas, quando for fóra de sua casa a seguir a demanda, e a demanda for com pessoa igual a elle, ou de maior condição. E não sendo a demanda com pessoa igual a elle, ou sendo a demanda em o lugar, onde he morador, contarão sómente as custas dos dias da pessoa a hum requerente seu, se o tiver, segundo a qualidade do requerente: convem a saber, se for peão, como a peão, e se for Scudeiro, ou homem de cavallo, como a Scudeiro, ou homem de cavallo. O que se entenderá, tendo o requerente procuração junta dos autos, porque então lhes contarão do dia, que offereceo a dita procuração.` },
        { id: 'of1-txci-26', number: '26', text: `E nos casos, em que assi mandamos contar as cavalgaduras a cada huma das ditas pessoas, se não trouxerem tantas, e trouxerem servidores de pé ou huma Azemela, ou duas, e requererem que lhes contem tantos servidores, ou Azemelas em lugar das cavalgaduras, contar-lhes-hão os servidores que trouxerem, contando-lhes para cada servidor a dozé réis como homem de pé: e assi cada huma Azemela com seu Azemel por huma cavalgadura, em quanto couber no numero das cavalgaduras. E isso mesmo, se trouxer mais de hum cavallo de sua pessoa, contar-lhe-hão até dous cavallos para sua pessoa, e hum delles será em conto das cavalgaduras, contando-lhe sómente a quinze réis para o cavallo.` },
        { id: 'of1-txci-27', number: '27', text: `E ás molheres de cada hum dos sobreditos, outros tantos homens e molheres por todos, como aos maridos, se os trouxerem seus, e alheios não, e da maneira que acima dissemos. E isto se entenda tambem em as molheres dos sobreditos, que viuvas forem. E se mais trouxerem, não lhes contem mais.` },
        { id: 'of1-txci-28', number: '28', text: `E em todos estes capítulos que fallam das cavalgaduras, que hão de ser contadas aos Mestres, Arcebispos, Bispos, Condes, e Prior do Crato, Commendatário de Alcobaça, Commendadores Móres, e ás pessoas de semelhante maneira, não se contarão nas ditas cavalgaduras as suas pessoas principaes: porque além das ditas cavalgaduras lhes contarão as suas pessoas.` },
        { id: 'of1-txci-29', number: '29', text: `E porque muitas vezes são chamadas algumas pessoas á Corte, ou ás Relações, e a outras partes, para testemunharem em feitos, que a elles não pertencem, ás quaes os Julgadores mandam algumas vezes pagar as custas da vinda, stada e tornada, mandamos que em taes casos lhes seja pago segundo o Regimento sobredito das custas, e mais o que de seus Officios e mesteres perderem, por irem assi fóra dar seus testemunhos. E outrosi se contarão segundo o dito Regimento, ao vencedor as custas, que fizer com as testemunhas, que vieram á Corte testemunhar a seu requerimento, para lhe serem pagas.` },
        { id: 'of1-txci-30', number: '30', text: `E os Contadores da Corte e Casa da Supplicação, e da Casa do Porto não passarão per si Cartas para as liquidações e contas, que fizerem. E quando se houverem de passar, as farão em nosso nome, assinadas pelos Juízes dos feitos, e passarão pela Chancellaria. E não as podendo elles per si screver, screverão no feito a informação do que tiverem necessidade de saber, ou de se provar: e com a dita informação mandarão o feito ao Scrivão, para passar as ditas Cartas assinadas pelos Juízes dos feitos, como dito he. E fazendo o contrario, serão suspensos de seus Officios.

Salario do Contador.` },
        { id: 'of1-txci-31', number: '31', text: `E o Contador contará para si da conta das custas, que assi fizer, seu salario per a maneira, que se segue: convém a saber, nos feitos, que se tratarem per aução nova, levará de cada conta, que fizer, trinta e seis réis, assi da que fizer do que monta ao Scrivão, ou Tabellião da parte do autor, como da que fizer do que lhe monta haver da parte do réo. E assi levará de ambas as ditas contas setenta e dous réis. E postoque haja tambem de fazer conta de dias de pessoa, por o autor, ou réo as vencerem, ou postoque as haja de contar a ambos, não levará cousa alguma. E isto haverá lugar em todos os Contadores; assi da Corte e Casa Supplicação, e da Relação do Porto, como em todos os de nossos Reinos.` },
        { id: 'of1-txci-32', number: '32', text: `E nos feitos, que per appellação vierem à Casa da Supplicação, ou do Porto, ou a qualquer Julgador, que per appellação possa conhecer, se vierem dante alguns Corregedores, ou Julgadores, de cujas sentenças se deva pagar dizima, e os ditos feitos forem sentenciados, e sem custas, ou custas do processo sómente, e as partes ambas houverem vista, levará da conta trinta e seis réis da parte do autor, e trinta e seis da parte do réo. E se nos ditos feitos forem julgadas custas de pessoa a huma só parte, postoque não houvesse vista, levará mais outros trinta e seis réis, e assi levará por todo cento e oito réis. E se a ambas as partes houver de contar custas de pessoa, levará de cada hum setenta e dous réis, e assi são por todos cento quarenta e quatro réis. Os quaes havemos por bem que leve, porquanto ha de fazer maiores contas por causa da dizima.` },
        { id: 'of1-txci-33', number: '33', text: `E se das ditas appellações não houver vista, nem custas de pessoa, levará sómente da conta, que fizer, dezoito réis.

E se huma só parte houver vista e outra não, levará da parte, que houve vista, trinta e seis réis, e da outra não leve nada.` },
        { id: 'of1-txci-34', number: '34', text: `E quanto he as appellações, que vierem dante os Juizes ordinarios, ou dante Julgadores, de cujas sentenças se não deva pagar dizima, se nellas houver vista de ambas as partes, ora haja condenação de custas de pessoa, ou do processo, ora não, levará da conta de cada hum trinta e seis réis. E se huma só parte houver vista e outra não, levará da conta daquelle parte, que a houve, trinta e seis réis, e da outra, que a não houve, não levará nada. E se huma parte e outra não houve vista, e a sentença for sem custas, levará sómente dezoito réis. E havendo vencimento de custas, ora seja do processo, ora de pessoa, levará daquela conta, que faz da parte, em que ha custas, trinta e seis réis, e da outra parte não levará cousa alguma.` },
        { id: 'of1-txci-35', number: '35', text: `E quanto ás contas, que fizerem nos feitos de aggravo, levarão o que hão de levar dos feitos das appellações, segundo a distinção, que acima fizemos nas ditas appellações.` },
        { id: 'of1-txci-36', number: '36', text: `E quando as partes ambas não fôrem presentes ao contar das custas, para ambas deverem de pagar ao Contador seu trabalho, ponha-se a paga das contas à parte, que for presente, e ella as pague. E no encerramento das custas, carregue-o o Contador na somma à outra parte, de maneira que a parte, que as pagou, as leve na sua somma, para lhas haver de pagar a outra parte, que não foi presente ao fazer da conta.` },
        { id: 'of1-txci-37', number: '37', text: `E os Contadores saibam das partes, quanto he o que lhes levaram os Scrivães, Tabelliães e Porteiros. E se acharem que levarem mais do que per nossas Ordenações, ou seus Regimentos lhes hé taxado, façam logo tornar à parte em dobro o que lhe mais levaram, como se contém no Titulo 84: Do que hão levar os Tabelliães. E quanto à mais pena, que os ditos Officiaes por isso merecerem, a haverão quando por isso forem accusados perante os Juizes competentes. E quando os Scrivães não mandarem os feitos aos Julgadores, ou Advogados nos termos, em que os devem mandar, o Contador lhes descontará de seus salarios as custas do retardamento.` },
        { id: 'of1-txci-38', number: '38', text: `E o Contador das custas não contará feitos alguns, em que haja de haver salario como Scrivão, ou Enqueredor. E isso mesmo nenhum Tabelliào, nem Scrivão, nem Enqueredor será Contador do feito, de que ha de haver salario. E fazendo cada hum dos sobreditos o contrario, perca o Officio, para o darmos a quem nossa mercê for.` },
        { id: 'of1-txci-39', number: '39', text: `E mandamos que a parte, que vencer contra algum preso, faça levar logo ao outro dia seguinte o feito ao Contador. E se mais retardamento fazer levar, pague as custas do retardamento. E isso mesmo será obrigado levar a sentença, que houve contra o preso, o dia, que lhe pelo Contador for dado para a levar á terra, onde o preso stá. E não a levando ao dito tempo, pagará as custas do que mais retardar, em dobro. E o Contador contará os feitos dos presos do dia, em que lhe forem dados, a dous dias, sob pena de lhes pagar as custas do retardamento em dobro. E isto se não entenderá nos presos da cadea de cada huma das Relações, ou da cidade de Lisboa, ou do lugar do Juizo, em que se despachou finalmente na mór alçada: porque nestes os presos condenados nas custas as poderão mandar contar pelos mesmos feitos. E tirando suas sentenças, e pagando, ou consignando em Juizo as custas, em que forem condenados, os Juizes os mandarão soltar, se outras culpas lhes não saírem nas folhas.` },
        { id: 'of1-txci-40', number: '40', text: `E o dito Contador, quando contar as custas, carregará sobre a parte condenada nellas a ássinatura, que se pagar das sentenças.` },
      ],
    },
    {
      id: 'titulo-xcii',
      title: `XCII. De como se hão de contar os salarios aos Procuradores`,
      type: 'articles',
      articles: [
        { id: 'of1-txcii-preambulo', number: 'Preâmbulo', text: `Aos Procuradores dos feitos contarão de Como esta pratica está em desuso, e nos parece honesta e digna de observar-se, citaremos aqui as palavras do referido Valasco, grande mestre de jurisprudencia, e seguro Mentor nos delicados deveres do Advogado:

« Et in hoc Regno, quia nullus potest in caussa propria advocare, quod sanctissime servatur apod omnia Tribunalia, propter peculiarem, et vehementem affectionem, quam presumitur qui ad propriam causam habere, et jubetur, ut advocatus litigans in caussa propria, per alium advocatum, quem constituerat, dicam suam causam, omnes extra dubium propositae questionis.

« Et ita hodie etiam salarium advocationis inter alias expensas litis adnumeratur actori, qui obtinuit, licet ipse advocatus sit, cum lege jubente per alium advocatum caussa suam egerit. »

Mas se na propria causa fôr o Advogado patrono, não deve cobrar os respectivos salarios. Ord. deste liv. t. 91 § 23, e deste t. §§ 8 e 9.

salario dos feitos civeis a quarentena do que vencerem, ou defenderem, até quantia de setecentos e vinte réis. E porque pode haver algumas duvidas, ter-se-ha esta maneira no contar delles. Quando se ordenar hum feito de grande quantia sobre scriptura publica, se a parte, contra quem se dá tal scriptura, pede vista, e vem com embargos, e não lhe he delles conhecido, e o Juiz sem embargo delles procede no feito, dando nelle final determinação, em tal caso haverá o Procurador o terço do dito salario.` },
        { id: 'of1-txcii-1', number: '1', text: `E se dessa aução, assi posta per scriptura publica, a parte pede vista, e allega alguma razão, ou embargos, que lhe são recebidos, em prova da qual dá outras scripturas, e se razoa sobre isso, é o feito he logo determinado pelas scripturas sem prova de testemunhas, então haverá o Procurador as duas partes do dito salario.` },
        { id: 'of1-txcii-2', number: '2', text: `E se a parte vier com embargos à scriptura, e lhe forem recebidos, e sobre elles dér prova de testemunhas, sobre o que tudo se dér a sentença, haverá o Procurador, que vencer, ou defender, o salario inteiro, se o vencimento chegar a quantia, porque o deva levar, segundo adiante será declarado.` },
        { id: 'of1-txcii-3', number: '3', text: `E ordenando-se algum feito, que seja de pequena quantia, assi sobre cousas de raiz, como moveis, e durar muito tempo, e o Procurador levar em ello grande trabalho, ou por serem muitas scripturas, que haja de ver, ou o ponto de Direito tal, que convenha ao dito Procurador studar sobre ello: e póde acontecer de tal feito não montar a este Procurador de quarentena de seu salario de dez até vinte réis: quando o Contador tal feito houver de contar, lhe alvidrará o salario, que lhe parecer que merece, com tanto que não chegue ao salario inteiro. E se tiver duvida, e o feito se tratar na Casa da Supplicação, ou na do Porto, communique-a com o Juiz da Chancellaria, e nos outros lugares com o Juiz do feito. E estes salarios se entendam nos feitos, que esses Procuradores novamente criam, e procuram até sentença diffinitiva.` },
        { id: 'of1-txcii-4', number: '4', text: `E em os feitos civeis, que vem per appellação, ou aggravo aos Desembargadores de cada huma de nossas Relações, contarão aos Procuradores a quarentena do que vencerem, ou defenderem até quantia de trezentos e sessenta réis, e mais não: por que nestes levam menos trabalho, que nos que criam de novo.` },
        { id: 'of1-txcii-5', number: '5', text: `E quando vierem os feitos á Corte per appellação, ou aggravo sómente sobre o libello, ou outra interlocutoria, de que se deva receber appellação, e ficar logo na Corte, se depois crescer tanto o processo em scriptura, que leve o Procurador nelles grande trabalho, contar-lhe-hão quinhentos e quarenta réis. E nos outros feitos, em que já vêm tiradas as inquirições, e depois na Corte per scripturas, ou interlocutorias, a que se dão inquirições, crescem tanto, como o que vem da terra, ou pouco mais, ou menos, nestes taes feitos contar-se-ha ao Procurador até quantia de quatrocentos e oitenta réis.` },
        { id: 'of1-txcii-6', number: '6', text: `E nos feitos das injurias verbaes, em que não cabe pena de Justiça, contarão aos Procuradores a quarentena, assi como nos feitos civeis.` },
        { id: 'of1-txcii-7', number: '7', text: `E nos instrumentos de aggravo, Cartas testemunhaveis, dias de apparecer, em que as partes fazem Procuradores, ou sem procuração lhos dão a razoar, e sómente põem nas costas hum razoado, e assi os levam aos Julgadores, e no dia de apparecer fazem apregoar a parte, e vão logo conclusos, sem mais escreverem em elles, em tal caso não contarão aos Procuradores a quarentena, sómente lhes contarão o que lhes parecer, segundo for o trabalho e crescimento do instrumento, em que se razoa.` },
        { id: 'of1-txcii-8', number: '8', text: `E se a parte manda da terra algum Procurador á Corte, que sollicite e procure seu feito, e esta parte per si razoa, sem tomar Procurador, se for vencedor em custas, farão pergunta a esse Procurador, se quer antes levar a quarentena do que venceo, ou defendeo, como he taxado aos Procuradores do numero, ou se quer antes os dias de pessoa, segundo a declaração feita nesta Ordenação. E o que escolher, lhe contem, de maneira que não levem dias de pessoa e salario, salvo os dias, que poser no caminho de ida e vinda.` },
        { id: 'of1-txcii-9', number: '9', text: `E se a parte principal, ou seu Sollicitador, ou requerente não quizer tomar Procurador, nem elle souber procurar e buscar algum Letrado, que de fóra lhe faça as razões, sem ver o feito, e essa parte presentar as razões nas audiencias, e for vencedor em custas, dar-lhe-hão juramento, quanto deo ao Letrado por lhe fazer as razões, e isso lhe contem, se virem que são feitas per Letrado: com tanto que não passe de duzentos réis, postoque a quantia do que vencer seja grande: porque parece, que não teve grande trabalho, pois não vio o processo.` },
        { id: 'of1-txcii-10', number: '10', text: `E não contarão salario ao Procurador do numero, se lhe não acharem feita procuração no processo, e se o contarem, paguem-no de sua casa a parte condenada: salvo nos feitos crimes dos presos, porque nestes per costume antigo os Procuradores podem procurar pelos presos, como ajudadores, postoque não tenham procuração. E em este caso lhes contarão seu salario, como adiante se dirá.` },
        { id: 'of1-txcii-11', number: '11', text: `E por não haver duvida, como se hão de contar estes salarios, quanto pertence ao vencer e defender, verá o Contador aquillo, que ao autor he julgado do principal na sentença, sem ter respeito ao que he pedido no libello; e do que for julgado, contará a seu Procurador a quarentena até a dita quantia. E quanto a defender, verá o que o autor pedio no libello, e daquillo, que o réo vai absoluto, contará a seu Procurador a quarentena, até quantia de setecentos e vinte réis, como he declarado no principio. E se todo o que o autor pedia em seu libello, lhe for julgado, de todo seu Procurador haverá a quarentena, até a quantia sobredita. E se o réo for absoluto de todo o que contra elle pedido era, de todo isso, de que he absoluto, contarão a seu Procurador a quarentena, até a dita quantia. E a quarentena, que assi o dito Procurador ha de levar de seu salario, se entenda de toda a condenação, ou absolvição, em que o réo seja condenado, ou absoluto, assi do principal, como do accessorio, assi de penas, como de interesses, fructos, ou danificamentos, ou qualquer outra cousa semelhante. Em tal maneira, que a dita quarentena não seja contada per respeito sómente da condenação do principal, mas de toda a condenação, assi do principal e accessorio, como dito he. E se em toda a dita quarentena montar mais que setecentos e vinte réis, não levará mais. Porém não se entenderá na dita quarentena a condenação das custas, porque as custas se julgam tanto, e mais por arbitrio do Julgador, que por rigor de Justiça. E por tanto não he razão, que por respeito dellas se julgue a quarentena do Procurador: salvo se as ditas custas forem julgadas per virtude de alguma obrigação, em que algum prometia, que não cumprindo o principal, pague todas as custas, que sobre elle forem feitas. Porque em tal caso será contada a quarentena ao Procurador, assi por respeito das custas, como do principal, seguido acima dito he da condenação do accessorio, fructos e penas.` },
        { id: 'of1-txcii-12', number: '12', text: `Item, nos feitos crimes de grandes maleficios, como morte de homem, aleive, ladroice, moeda falsa, ou outro semelhante, que sendo provado contra o accusado, morreria por o tal crime, contarão ao Procurador novecentos réis, se elle começou o feito, e o procurou até sentença diffini tiva. E quando taes feitos de crimes graves vierem per apelação a cada huma das Relações, contarão ao Procurador, que vencer, ou defender, quatrocentos e cincoenta réis, e mais não. E quando o feito crescer no caso da apelação outro tanto, ou mais, como o que vem da terra, quando o tal feito for visto per o Contador, contará a esse Procurador quinhentos e quarenta réis, se o Contador vir que o feito o merece.` },
        { id: 'of1-txcii-13', number: '13', text: `E nos feitos crimes, em que não cabe pena de morte, postoque provado fosse o malefício, mas deve o réo ser degradado, ou açoutado, ou ser-lhe decepada huma mão ou pé, ou outra pena semelhante, contarão ao Procurador, que vencer, ou defender, quinhentos e quarenta réis, se começou o feito de novo, e o tratou até sentença diffini tiva. E se veio per apelação, contar-lhe-hão duzentos e setenta réis, se ao Contador parecer que os merece.` },
        { id: 'of1-txcii-14', number: '14', text: `E por que alguns feitos, que vem per apelação, são de pequeno volume, postoque de grandes maleficios, e o Procurador põe em os ver sómente huma hora, e faz hum só razoado, e não he A faculdade concedida nesta Ord. estende-se ao caso da Ord. do liv. 3 t. 7 § 3.

razão que leve o salario, como nos feitos grandes, contar-lhe-ha o Contador o que em sua consciencia lhe parecer que merece. E se tiver dúvida, falle com o Juiz da Chancellaria, sendo em cada huma das Relações, ou com o Juiz do feito, que em nosso nome desembargar as taes appellações, não sendo nas ditas Relações.` },
        { id: 'of1-txcii-15', number: '15', text: `E quando os taes feitos forem per appellação aos Ouvidores dos Mestrados, ou de outros Senhores de terras, contarão aos Procuradores apetados do que mandamos contar aos Procuradores da Corte. E se perante os ditos Ouvidores se tratarem alguns feitos per nova aucão (por terem para isso nossa Provisão), contarão aos Procuradores todo o salario, que acima mandamos contar aos Procuradores nos feitos de auções novas.` },
        { id: 'of1-txcii-16', number: '16', text: `Item, os Contadores saibam das partes quanto lhes levaram aos Procuradores; e se acharem que lhes levaram mais do que lhes per este Regimento he taxado, e as partes lhes requererem que lhes façam tornar o que assi mais lhes levaram, o Contador lho fará tornar, sem por isso o Procurador haver outra pena alguma.` },
        { id: 'of1-txcii-17', number: '17', text: `E os salarios dos Procuradores nos feitos, que novamente começarem, hão de ser pagos, huma terça parte quando o libello for recebido, outra quando as inquirições forem abertas e publicadas, e a outra quando o feito for findo per sentença difinitiva.` },
        { id: 'of1-txcii-18', number: '18', text: `E sendo as partes presentes no lugar, onde os Procuradores forem moradores, elles demandarão seus salarios do dia, em que se publicar a sentença difinitiva, em que elles foram Procuradores até tres mezes. E não os demandando no dito tempo, não os poderão mais demandar, nem serão sobre isso ouvidos.

Qual o modo de executar esta disposição de Custas? Nem não provinio o novo Regulamento de Justice?

Parece-nos que cahio em desuso a presente Ord.` },
      ],
    },
    {
      id: 'titulo-xciii',
      title: `XCIII. Do salario, que hão de levar os Caminheiros`,
      type: 'articles',
      articles: [
        { id: 'of1-txciii-preambulo', number: 'Preâmbulo', text: `Os Caminheiros hão de haver das partes de trazerem as appellações à Corte e nossas Relações, por cada appellação a razão de cinco réis por cada huma-legoa, que houver do lugar, donde partirem até à Corte, ou lugar onde stiver a Relação. E isto até o salario chegar a cento e cincoenta réis, e mais não. E postoque haja mais legoas daquellas, por que lhes hajam de contar os cento e cincoenta réis, não haverão por isso mais.` },
      ],
    },
    {
      id: 'titulo-xciv',
      title: `XCIV. Que não tenham Officios publicos os menores de vinte cinco annos, nem os homens solteiros`,
      type: 'articles',
      articles: [
        { id: 'of1-txciv-preambulo', number: 'Preâmbulo', text: `Mandamos, que nenhuma pessoa sirva Por identidade de razão, estas disposições se applicam aos Officios de Justiça, aos Districtuidores, Contadores, Partidores, etc.

Ad instar dos Advogados, a prescripção destes mezes divida deverá correr depois de expirados os tres diez da ultima molestia.

Os autos não devem ser remetidos de um para outro Juiz sem citação da parte. Ord. do liv. 3 t. 20 § 9, e t. 87 § 14.

Oficio algum de Justicia, nem da Fazenda, de qualquer qualidade que seja, nem da Governança das cidades, villas e lugares de nossos Reinos, que lhes seja dado, nem o possa servir em nome de outrem, postoque tenha licença de Nós para isso, não passando de idade de vinte cinco annos. E fazendo o contrario, perça o Officio, se for seu, e nunca o mais haja. E não sendo seu, perderá a estimação delle, ametade para quem o accusar, e a outra para os Captivos. E sendo Juizes dos Orfãos, serão de idade de trinta annos, e dahi para cima, como fica dito em seu Regimento.` },
        { id: 'of1-txciv-1', number: '1', text: `E qualquer pessoa, a que for dado Officio de julgar ou de screver, não sendo casado, será obrigado a se casar, dentro de hum anno do dia, que lhe for dado, sob pena de perder o dito Officio. E os que houverem de servir de Provedores de Comarcas, não serão provedores, sem serem casados. E se depois dos ditos Officiaes serem casados, viuvarem, serão obrigados a se tornarem a casar dentro de hum anno do dia em que assi viuvarem, sob a mesma pena: salvo se ao tempo, que houverem os Officios, ou ao tempo em que viuvarem, passarem de quarenta annos: porque em tal caso não serão obrigados a se casar.` },
      ],
    },
    {
      id: 'titulo-xcv',
      title: `XCV. Que os Julgadores temporaes não casem com molheres de sua jurisdição`,
      type: 'articles',
      articles: [
        { id: 'of1-txcv-preambulo', number: 'Preâmbulo', text: `Por muitos inconvenientes, que se seguem de os Julgadores temporaes casarem com molheres de sua jurisdição, durando o tempo de suas Judicaturas, e ser o sobre dito muito contra o serviço de Deus e nosso, e boa administração da justiça, que rende nisso prover, mandamos que os Corregedores das Comarcas, Provedores, Ouvidores dos Mestrados, Ouvidores dos Senhores das terras, e os Juizes de fóra das cidades, villas e lugares de nossos Reinos e Senhorios, durando o tempo de seus Officios, não casem para palavras de presentes sem nossa licença com molheres de lugares, ou Comarcas, em que forem Julgadores, nem com molheres, que nas ditas Comarcas stêm com tenção de nellas morar, postoque dellas, ou dos ditos lugares não sejam naturaes. E casando sem nossa licença, por esse mesmo feito fiquem suspensos dos taes cargos, para Nós delles provermos, como houvermos por bem. E tudo o que nos ditos cargos lizerem depois do casamento celebrado, seja nenhum e de nenhum effeito: e pagarão ás partes todas as custas, perdas e danos, que por essa causa receberem. E querendo algum delles casar com alguma das ditas molheres, haverá para ello primeiro nossa licença. E os Julgadores, que nas partes da India nos servirem, pedirão a tal licença ao Viso-Rei, ou Governador della, o qual lha poderá dar, entendendo que nisso se não seguirá prejuizo algum a nosso serviço, nem a bem da justiça das partes.

tempo, não obstante o § 42 do Regimento novo do Desembargo do Paço.` },
      ],
    },
    {
      id: 'titulo-xcvi',
      title: `XCVI. Dos que vendem, ou renunciam os Officios sem licença del-Rei, ou stando doentes, ou tendo nelles feito alguns erros`,
      type: 'articles',
      articles: [
        { id: 'of1-txcvi-preambulo', number: 'Preâmbulo', text: `Mandamos, que os Tabelliães, Scrivães e quaesquer outros nossos Officiaes, não possam vender os Officios, que de Nós tiverem, nem traspassar, nem renunciar em outrem sem nossa special licença. E vendendo-os, perça o vendedor o preço que receber, ou sperar de receber, e mais o dito Officio, e o comprador o não possa haver, e fique a Nós, para o darmos a quem for nossa mercê.` },
        { id: 'of1-txcvi-1', number: '1', text: `E assi mesmo o tal Official o não poderá renunciar, quando stiver doente de doença perigosa de morte. E se o renunciar, stando doente da dita maneira ou de qualquer doença, de que venha a fallecer do dia, que a renunciação fizer, a trinta dias, não valerá a renunciação, e o Officio se perderá, para o Nós darmos a quem for nossa mercê: postoque per bem da dita renunciação fosse o Officio já dado a outrem per Nós, ou per quem poder tivesse de o dar.` },
        { id: 'of1-txcvi-2', number: '2', text: `Outrosi, não poderá renunciar, nem vender, postoque para isso tenha nossa auctoridade, quando nelle tiver feitos alguns erros, porque o deve perder. E renunciando-o, ou vendendo-o, poderá depois ser accusado polos ditos erros, postoque o Officio já stê em poder de outro Official, a quem tenhamos feito mercê delle per virtude da dita renunciação. E será condenado aquelle, que o dito Officio renunciou, na valia delle, ametade para quem o accusar, e a outra para nossa Camera: e mais haverá qualquer outra pena de justiça, a que com direito for obrigado polos taes erros. Porém neste caso, pola pena da valia do Officio, se o não começarem a accusar do dia que fez a renunciação, a dous annos, não poderá mais por ella ser accusado, nem demandado. E quanto á pena crime, poderá ser accusado e punido dentro no tempo, que per Direito os taes crimes podem ser accusados. E aquelle, a que tivermos feito mercê do dito Officio per virtude da tal renunciação, não o perderá polos erros, que tinha feito o que o renunciou.` },
        { id: 'of1-txcvi-3', number: '3', text: `E por se evitarem os inconvenientes, que se podem seguir de os Officiaes venderem seus Officios, mandamos, que quando se livrarem de culpas, ou erros, que nelles tenham commettidos, os Julgadores os não condenem, que os vendam ou renunciem, mas os condenarão nas penas, que por suas culpas, ou erros mereceram.` },
      ],
    },
    {
      id: 'titulo-xcvii',
      title: `XCVII. Que os Officiaes sirvam per si seus Officios`,
      type: 'articles',
      articles: [
        { id: 'of1-txcvii-preambulo', number: 'Preâmbulo', text: `Polos muitos inconvenientes, que se seguem de os Officiaes não servirem seus officios per si, e os arrendarem e servirem per outrem, mandamos a todos os Officiaes de nossos Reinos e Senhorios, assi da Justiça, como da Fazenda, e Scrivães de nossa Camera, que sirvam per si seus Officios, e não ponham outras pessoas, que por elles os sirvam. E qualquer Official, que poser outrem, perca o Officio, em que o assi poser, para o darmos a quem for nossa mercê; e o que servir, perca a valia delle ametade para quem o accusar, e a outra para nossa Camera. E se no dito Officio fizer algum erro, será castigado com todas as penas, que merecêra, se fôra proprietario do dito Officio, em que commetter o tal erro, ou erros.

S. R. p. 1 t. 39 l. 1.` },
        { id: 'of1-txcvii-1', number: '1', text: `E quando por justos respeitos fizermos mercê a algum Official, que possa pôr outrem para servir em seu Officio, o dito Official porá em seu lugar tal pessoa, que o possa e saiba bem servir. E bem assi, Ainda hoje existem desses proprietarios, que fruem os direitos adquiridos.

Quem possuia dous Officios devia, dentro de seis mezes, renunciar um.

quando Nós dermos lugar a algum, que sirva por algum Official a seu requerimento, nomeando-nos elle a pessoa, que haja de servir, devem os subrogados ser vistos e examinados pelos Julgadores, perante quem houverem de servir. E sendo per elles approvados, poderão servir em lugar dos ditos Officiaes o tempo, para que houverem a dita licença, e de outra maneira não. E quando estes Officiaes houverem de pôr as ditas pessoas, para por elles servirem per nossa licença, ou as nomearem, e Nós lho concedermos, os buscarão taes, que não hajam de fazer erro nos ditos Officios de qualidade, porque os mereçam perder; porque fazendo-o, os ditos Officiaes perderão os Officios, como se per si fizessem os taes erros, sem mais haverem outra pena. E a pessoa, que o dito erro fizer, pagará a estimação do Officio, para quem Nós mandarmos. E mais haverá qualquer outra pena, que per Direito merecer, segundo o erro for.` },
        { id: 'of1-txcvii-2', number: '2', text: `E quando alguma pessoa vier à Côrte pedir a Nós algum Officio, ou servintia delle, ou aos Vêdores da nossa Fazenda, pertencendo-lhes per seu Regimento, se os taes Officios forem da administração da Justiça, tragam logo certidão do Corregedor, posto per Nós na Comarca, donde o Officio for, da qualidade do Officio, e se he vago, e por cujo fallecimento, e de que maneira vagou. E sendo servintia, da razão, ou impedimento, que tem o proprietario delle, e da necessidade, que ha, de se servir: e bem assi da qualidade, costumes e habilidade da pessoa, que a pede: e sendo da Fazenda, trará certidão do Contador da Comarca. E sem as ditas certidões não lhes sejam tomadas petições, per que peçam o Officio, nem servintia, nem se lhes dê despacho. As quaes informações os ditos Corregedores, e Contadores tomarão em segredo, para que mais livremente digam a verdade, de pessoas sem suspeita, que tiverem mais razão de o saber, dando-lhe juramento, e as enviarão per suas Cartas cerradas e selladas, com seu parecer. E sendo-lhes pedidas per muitas pessoas sobre hum mesmo Officio, a todas as darão, para Nós provermos a quem nos aprouver. E isto não havendo criados nossos, a que tenhamos obrigação, que os peçam; porque a elles se darão, antes que a outras pessoas, sendo da nossa dada, ou não dispondo Nós per outra maneira dos ditos Officios.` },
        { id: 'of1-txcvii-3', number: '3', text: `E quando algum Scrivão da Camera, ou da Almotaceria, ou Tabellião do publico, ou Judicial, Enqueredor, Contador, Distribuidor, for impedido por absencia, doenças, suspensão, ou homizio, de maneira que não possa, ou não deva servir, ou tiver Provisão nossa, para per algum tempo não servir seu Officio, os Corregedores e Ouvidores dos Mestrados, cada hum em sua Comarca, encarregarão as servintias a outro Official de semelhante Officio, se no tal lugar o houver, que mais apto for, e que com menos prejuízo das partes o possa servir. E não havendo no tal lugar mais Officiaes, que o impedido, encarregarão a tal servintia a hum criado nosso, que para isso for sufficiente. E não o havendo, encarregai-o-hão a huma pessoa do mesmo lugar de boa consciencia, e apto para o dito Officio. E quando o Official for suspenso por erros, não encarregarão a servintia a parente do tal Official suspenso, nem de sua molher, dentro no segundo grão.` },
        { id: 'of1-txcvii-4', number: '4', text: `E as sobreditas commissões farão per tempo de hum anno, se tanto durar o impedimento. E durando mais do dito anno, e constando-lhes, que serviram bem, lhes encarregarão as servintias per mais outro anno, se tanto houver de durar o impedimento. E os Provedores e Contadores, quando os Scrivães dos Orfãos, Hospitaes, Capellas, ou Residuos pela sobredita maneira forem impedidos, encarregarão a servintia a hum Scrivão, ou Tabellião, que no dito lugar houver.` },
        { id: 'of1-txcvii-5', number: '5', text: `E os ditos Corregedores, ou Provedores, farão dar juramento dos Sanctos Evangelhos ás pessoas, que assi encarregarão, que bem e verdadeiramente sirvam; de que se fará assento pelos Corregedores nos livros das Chancellarias das Comarcas, e pelos Provedores nos livros das Provedorias, e serão assinados per elles, e pelas pessoas, a que assi encarregarem. E sendo Officio de Tabellião, em que se haja de fazer sinal publico, o fará no dito assento. E terá livro de Notas e livro de querelas, assinado pelo Juiz do lugar, como he obrigado ter o proprietario. E nos sobreditos casos, em que os Corregedores e Provedores fizerem as taes commissões, lhes passarão mandados, para os Juizes e Justiças os deixarem servir o dito tempo.` },
        { id: 'of1-txcvii-6', number: '6', text: `E sendo caso que os impedimentos hajam de durar mais que dous annos, os Corregedores, Provedores e Contadores nol-o farão a saber, screvendo-nos declaradamente, que Official he, e a razão e tempo do impedimento, e que pessoas ha no tal lugar, aptas para as ditas servintias, e cujos criados são, e que qualidades tem, e se as pessoas, que serviram o dito tempo, o fizeram como deviam, para Nós provermos, como houvermos por nosso serviço.` },
        { id: 'of1-txcvii-7', number: '7', text: `E as servintias dos Officios das cidades de Lisboa, Evora, Coimbra, Porto, e da villa de Santarem, e dos Officiaes das Correições, Provedorias e Contadorias das Comarcas, proverão os ditos Corregedores, Provedores e Contadores per tempo de tres mezes. E nol-o farão saber na maneira acima dita, para provermos, como for nosso serviço. E sendo terras de Senhores, onde Corregedores não entram per via de correição, os Provedores das Comarcas, que entram nos taes lugares, proverão per tempo de seis mezes sómente, e nos screverão pela maneira sobredita. E os Senhores de terras (postoque a elles pertença, per bem de suas doações a dada dos Officios), nem seus Ouvidores, não se entremetterão no provimento das ditas servintias: porquanto confórme a nossas Ordenações e a Direito, a Nós sómente pertence prover nellas. E nas servintias dos Officios das Casas da Supplicação, e do Porto, guarda-se-ha o que temos dito no Titulo 1: Do Regedor.` },
        { id: 'of1-txcvii-8', number: '8', text: `E sendo impedido, ou suspenso o Juiz dos Orfãos de qualquer lugar, servirão os Juizes ordinarios, ou o Juiz de fóra, si o hi houver, emquanto Nós não mandarmos o contrario. E sendo suspensos, ou impedidos os Scrivães dos Orfãos dos lugares, em que per Nós são postos Juizes de fóra, elles proverão as servintias per tempo de tres mezes sómente, nos quaes nol-o farão saber pelo modo acima dito.` },
        { id: 'of1-txcvii-9', number: '9', text: `E todas as pessoas, a que forem encarregadas as servintias, terão em boa guarda todos os livros e papeis, que lhes forem entregues, e os que elles screverem no tempo, que assi servirem: os quaes entregarão per inventario ao proprietario do Officio, ou ao que delle novamente fôr provido, ao tempo, que houver o tal Officio, e cobrarão delle conhecimento para sua guarda. E não o fazendo assi, incorrerão nas penas, em que incorrem os Officiaes que não dão conta dos papeis, que são obrigados.` },
        { id: 'of1-txcvii-10', number: '10', text: `E o Scrivão, que houver Provisão nossa, para ter pessoa, que o ajude a screver, terá huma pessoa sómente, que screva em todas as cousas, sobscrevendo-as elle. Porém não screverá os termos das audiencias, inquirições, querelas, e as outras cousas, que fôrem de segredo de Justiça, porque estas taes tomará e screverá o Scrivão per si. E o dito Screvente será maior de quatorze annos, e examinado pelo Juiz a que pertencer. E sendo suficiente, lhe será dado juramento. E de que se fará assento nas costas da Provisão. E falle- "... e que nenhum Escrivão do Crime possa trasladar as devassas senão por sua propria mão, sem embargo de qualquer uso, e costume, ou sentenças, que houver em contrário, porque tudo hei por derogado; e que os que assim o não cumprirem, sejão suspensos de seus Officios até minha mercê."

Porém porque poderá acontecer haver algumas, que por serem muito grandes, as não possam os Escrivães trasladar por sua propria mão, ou de tão pouca substancia, que importa pouco deixarem de o fazer; nestes casos, hei por bem que elles peçam licença aos Juizes das taes devassas, para as poderem fazer trasladar por seus Escreventes, e que elles (se assi lhe parecer) lha possam dar em escrito, a qual se porá no principio do traslado de cada huma, para que conste, que se fez com sua authoridade; e que os Corregedores, e Juizes do Crime da cidade, que despacharem as taes devassas, não sendo trasladadas por mão dos proprios Escrivães, ou de seus Escreventes na fórma, que fica dito, hajam por isso as penas que bem parecer ao Regedor; e os Corregedores da Corte, que o assi o não cumprirem sejam por elle severamente reprehendidos.* Esta disposição tambem se applica no Civel, quando os autos e peças a trasladar são extensos ou de fraca importancia.

cendo o dito Screvente, ou tendo outro impedimento, o Scrivão poderá nomear outro, que lhe será recebido na sobredita maneira. E os ditos Screventes não irão ás audiencias tomar por os Scrivães os termos, aindaque elles lho mandem, nem os Julgadores lho consentirão.` },
      ],
    },
    {
      id: 'titulo-xcviii',
      title: `XCVIII. Quanto tempo duram as Cartas impetradas per — se assi he, e do que houve perdão, depois dellas serem impetradas`,
      type: 'articles',
      articles: [
        { id: 'of1-txcviii-preambulo', number: 'Preâmbulo', text: `Porquanto muitas pessoas impetram de Nós, ou de nossos Officiaes, que para isso nosso poder tem, Cartas de dadas de Officios, ou de alguma fazenda, ou de outras cousas, per — se assi he, e depois de as terem, se deixam star, sem citarem nem demandarem as partes contrarias, de que se seguem muitos inconvenientes; mandamos Os direitos destes empregados achão-se garantidos por diferentes actos da antiga legislação.

que a pessoa, que impetrar tal Carta, cite a parte contraria dentro de seis mezes do dia, que a Carta for feita. E não o começando a demandar dentro no dito tempo, não poderá jamais em tempo algum demandar seu adversario pela dita Carta, e a mercê, que per ella lhe era feita, será de nenhum effeito. E havendo neste tempo dos seis mezes a parte contraria de Nós perdão, não prejudicará ao impetrante, que já tinha nossa Carta passada pela Chancellaria.` },
      ],
    },
    {
      id: 'titulo-xcix',
      title: `XCIX. Como ElRei póde tirar os Officios da Justiça e da Fazenda, sem ser obrigado a satisfação`,
      type: 'articles',
      articles: [
        { id: 'of1-txcix-preambulo', number: 'Preâmbulo', text: `Porquanto por confiarmos de algumas pessoas, que nos serviram bem e fielmente, e como cumpre a nosso serviço e bem da Justiça, descargo de nossa consciencia e proveito de nossa Fazenda, os encarregamos de alguns Officios da Justiça, ou da nossa Fazenda, e assi por lhes fazermos mercê (a qual porém lhes não faríamos, postoque boa vontade lhes tenhamos, se não fosse a confiança, que nelles temos), e depois de os assi termos encarregados nos taes Officios, vêm ás vezes á nossa noticia, que os não servem como são obrigados, e conforme a confiança, que nelles tinhamos, quando dos taes Officios os provermos. E postoque nas cousas, que assi dos sobreditos sabemos, e que à nossa noticia vem, ás vezes não ha provas tão claras, porém ha quanto basta para sermos certo, que somos delles mal servido, e elles errarem nos ditos Officios, de maneira que será mais serviço de Deos e nosso serem-lhes tirados, que deixal-os star nelles.

Polo que, e por outros respeitos, que nos movem, de muito serviço de Deos e nosso, bem da Justiça e governo de nossos Reinos e Senhorios, determinamos, que quaesquer Officios, que dermos, assi da Justiça, como de nossa Fazenda, ou de qualquer outra sorte e qualidade que seja, quando quer que Nós soubermos, e nos certificarmos em nossa consciencia, que alguns dos ditos Officiaes nos servem nelles mal, e fazem o que não devem, ou damnificam e roubam nossa Fazenda, lhos possamos tirar e dar a quem nossa mercê fôr, sem por isso lhes sermos em obrigação alguma, assi no foro da consciencia, como no foro judicial, para por isso haverem de demandar nosso Procurador, nem requerer a Nós satisfação, porque de todo os excluimos. E para se não poder allegar ignorancia, o declaramos per esta nossa Ordenação.` },
      ],
    },
    {
      id: 'titulo-c',
      title: `C. Como os Julgadores e outros Officiaes serão suspensos, quando forem accusados por erros`,
      type: 'articles',
      articles: [
        { id: 'of1-tc-preambulo', number: 'Preâmbulo', text: `Todo o Julgador, que for accusado por erro, que se diga ter commettido por malicia em seu Officio, porque provado mereceria perdêl-o, será suspenso delle, e dado, ou commettido a outro, que o sirva, até elle ser livre e achado por sem culpa do malefico. A qual suspensão se fará, tanto que o libello for recebido contra o accusado. E emquanto o libello não for recebido, não será o dito Julgador, assi accusado, suspenso, por se dizer, que he accusado, se outras culpas hi não houver, por que pareça ao Juiz da causa, que deva ser suspenso, antes de ser recebido o libello.` },
        { id: 'of1-tc-1', number: '1', text: `Porém, quanto aos Tabelliães e outros quaesquer Officiaes de Justiça, tanto que se mandar proceder contra elles por erros de seus Officios, ou tanto que por os ditos erros forem presos, os Julgadores os hajam logo por suspensos dos ditos Officios, e os não sirvam, até serem livres, postoque sejam accusados por erros de pessoas, que por elles sirvam. O que os ditos Julgadores cumprirão sob pena de serem suspensos de seus Officios, e de não servirem mais Officio da Justiça. E a mesma pena haverão os mesmos Tabelliães e Officiaes, que servirem.` },
        { id: 'of1-tc-2', number: '2', text: `E sendo os ditos Julgadores e Officiaes presos por outros crimes, fóra do Officio, em cadea publica, não poderão servir seus Officios, em quanto assi forem presos. Porém, a Nós ficará prover sobre as ditas suspensões, considerada a qualidade do accusador e accusado, como nos parecer serviço de Deos, e nosso.` },
      ],
    },
  ],
};
